/**
 * Enemy animation audit: checks the supplied pack (`assets-src/enemy-animations/`) against its `manifest.json`
 * (files, PNG signature, sheet size = frame count × cell) and every game sheet in public/assets/enemy-animations/
 * (generated by `scripts/normalize-enemy-animations.ts`) against the animation registry
 * (`src/render/enemy-animations.ts`). No browser and no dependency (`scripts/png.ts`).
 *
 *   npx vite-node scripts/audit-enemy-animations.ts            # per-frame table and warnings; exit code 1 on errors
 *   npx vite-node scripts/audit-enemy-animations.ts -- --write # regenerate src/render/enemy-animation-bounds.ts
 *
 * Per game clip: visible bounds (alpha > 16) as a share of the cell, centre of those bounds (share of the cell edge from
 * its middle, +x forward), coverage and the visible share of the cell's 1 px border (art cut by the edge, bleeding
 * from a neighbouring cell, a grid line). Per clip: the largest frame-to-frame jump of the alpha-weighted centre and of the visible size (pivot drift),
 * the loop seam (last → first frame) and the share of a frame's pixels that differ from the next (a frozen clip).
 * Errors: a missing or undecodable file, a sheet that does not divide into its declared cells, a blank frame, no alpha,
 * an opaque cell border. Warnings are for review by eye (`/gallery.html?anim`).
 */
import { readFileSync, writeFileSync } from "node:fs";
import type { EnemyId } from "../src/core/types";
import { ANIMATION_STATES, clipError, ENEMY_ANIMATIONS, type AnimationClip } from "../src/render/enemy-animations";
import { decodePng, measureArt, VISIBLE_ALPHA, type ArtMetrics, type Png } from "./png";

const ROOT = new URL("../", import.meta.url),
  BOUNDS_FILE = new URL("../src/render/enemy-animation-bounds.ts", import.meta.url);
const args = process.argv.slice(2);

interface ManifestClip {
  sheet: string;
  frameCount: number;
  frameWidth: number;
  frameHeight: number;
  fps: number;
  loop: boolean;
}
const manifest = JSON.parse(readFileSync(new URL("assets-src/enemy-animations/manifest.json", ROOT), "utf8")) as { enemies: Record<string, { states: Record<string, ManifestClip> }> };

/** Pivot drift between neighbouring frames (share of the cell) worth a look; above `DRIFT_ERROR` the clip jumps visibly. */
const DRIFT_WARN = 0.03,
  DRIFT_ERROR = 0.08;
/** Change of the visible longest side between neighbouring frames (share) worth a look. */
const SIZE_WARN = 0.12;

const errors: string[] = [],
  warnings: string[] = [];
const f2 = (v: number) => (v >= 0 ? " " : "") + v.toFixed(2);

/** One cell of a horizontal sheet as its own image. */
function cell(png: Png, i: number, w: number, h: number): Png {
  const rgba = new Uint8Array(w * h * 4);
  for (let y = 0; y < h; y++) rgba.set(png.rgba.subarray((y * png.width + i * w) * 4, (y * png.width + i * w + w) * 4), y * w * 4);
  return { ...png, width: w, height: h, rgba };
}
/** Share of pixels whose alpha differs by more than 24 between two cells. */
function changed(a: Png, b: Png) {
  let n = 0;
  for (let i = 3; i < a.rgba.length; i += 4) if (Math.abs(a.rgba[i] - b.rgba[i]) > 24) n++;
  return n / (a.width * a.height);
}
const longest = (m: ArtMetrics) => Math.max(m.visibleWidth, m.visibleHeight);
/** Share of a cell's 1 px border with visible pixels (alpha > `VISIBLE_ALPHA`): art cut by the cell edge. Fainter glow may reach it. */
function visibleBorder({ width: w, height: h, rgba }: Png) {
  let n = 0;
  for (let i = 0; i < w; i++) for (const [x, y] of [[i, 0], [i, h - 1], [0, i], [w - 1, i]]) if (rgba[(y * w + x) * 4 + 3] > VISIBLE_ALPHA) n++;
  return n / (4 * w);
}

// The supplied pack: every declared sheet exists, is a PNG and divides into its declared cells.
for (const [id, set] of Object.entries(manifest.enemies))
  for (const [state, m] of Object.entries(set.states)) {
    try {
      const png = decodePng(readFileSync(new URL(m.sheet, ROOT)));
      if (png.width !== m.frameWidth * m.frameCount || png.height !== m.frameHeight) errors.push(`source ${id}/${state}: ${png.width}×${png.height} is not ${m.frameCount} × ${m.frameWidth}×${m.frameHeight}`);
    } catch (e) {
      errors.push(`source ${id}/${state}: ${m.sheet}: ${(e as Error).message}`);
    }
  }
// Coverage: manifest ↔ registry.
const registered = Object.keys(ENEMY_ANIMATIONS) as EnemyId[];
for (const id of Object.keys(manifest.enemies)) if (!registered.includes(id as EnemyId)) errors.push(`${id}: in the manifest but not registered`);
for (const id of registered) if (!manifest.enemies[id]) errors.push(`${id}: registered but not in the manifest`);

const union: Partial<Record<EnemyId, { x0: number; y0: number; x1: number; y1: number; size: number }>> = {};
let decoded = 0,
  stored = 0;
console.log("clip            frames  cell     visible W×H       ctr x  ctr y  cover  edge    max drift  max size  seam   min change");
for (const id of registered) {
  const set = ENEMY_ANIMATIONS[id]!;
  for (const state of ANIMATION_STATES) {
    const clip: AnimationClip | undefined = set[state],
      declared = manifest.enemies[id]?.states[state],
      name = `${id}/${state}`.padEnd(16);
    if (!clip) {
      if (declared) errors.push(`${id}/${state}: in the manifest but not registered`);
      continue;
    }
    if (!declared) errors.push(`${id}/${state}: registered but not in the manifest`);
    // Frame counts and cells follow the re-cut game sheets; the timing must stay the manifest's.
    else if (declared.fps !== clip.fps || declared.loop !== clip.loop) errors.push(`${id}/${state}: registry and manifest timing disagree`);
    const problem = clipError(clip);
    if (problem) errors.push(`${id}/${state}: ${problem}`);
    let bytes: Buffer, png: Png;
    try {
      bytes = readFileSync(new URL(`public/${clip.path}`, ROOT));
      png = decodePng(bytes);
    } catch (e) {
      errors.push(`${id}/${state}: ${clip.path}: ${(e as Error).message}`);
      continue;
    }
    stored += bytes.length;
    decoded += png.width * png.height * 4;
    if (png.colorType !== 6) errors.push(`${id}/${state}: no alpha channel (colour type ${png.colorType})`);
    if (png.width < clip.frameWidth * clip.frames || png.width % clip.frameWidth || png.height !== clip.frameHeight)
      errors.push(`${id}/${state}: sheet ${png.width}×${png.height} does not hold ${clip.frames} cells of ${clip.frameWidth}×${clip.frameHeight}`);
    if (png.width & (png.width - 1) || png.height & (png.height - 1)) warnings.push(`${id}/${state}: ${png.width}×${png.height} is not a power of two (no mipmaps)`);
    // Padding cells after the last frame must be empty.
    for (let i = clip.frames; i < png.width / clip.frameWidth; i++)
      if (measureArt(cell(png, i, clip.frameWidth, clip.frameHeight)).coverage > 0) errors.push(`${id}/${state}: padding cell ${i + 1} is not empty (frame count too low?)`);
    const n = Math.min(clip.frames, Math.floor(png.width / clip.frameWidth)),
      cells = Array.from({ length: n }, (_, i) => cell(png, i, clip.frameWidth, clip.frameHeight)),
      metrics = cells.map(measureArt);
    let drift = 0,
      size = 0,
      minChange = 1;
    metrics.forEach((m, i) => {
      if (m.coverage < 0.002) {
        // A death clip may fade out completely on its last frame; anywhere else an empty cell is broken.
        if (state === "death" && i === n - 1) warnings.push(`${id}/${state}: last frame is empty (fade-out)`);
        else errors.push(`${id}/${state}: frame ${i + 1} is blank`);
      }
      // Art cut by the cell edge: a crop in the supplied frames (the drone's rotors) or a bad cut. Reviewed, so a warning.
      const edge = visibleBorder(cells[i]);
      if (edge > 0.08) errors.push(`${id}/${state}: frame ${i + 1} is cut along ${(edge * 100).toFixed(1)} % of its cell border`);
      else if (edge > 0) warnings.push(`${id}/${state}: frame ${i + 1}: visible art on ${(edge * 100).toFixed(1)} % of the cell border`);
      if (m.transparent < 0.2) errors.push(`${id}/${state}: frame ${i + 1} is nearly opaque (no transparent background)`);
      const next = metrics[i + 1] ?? (clip.loop ? metrics[0] : undefined);
      if (!next || next.coverage < 0.002 || m.coverage < 0.002) return;
      // Only idle and move need a stable pivot; hurt recoils and death breaks apart on purpose.
      const d = Math.hypot(next.center.x - m.center.x, next.center.y - m.center.y),
        s = Math.abs(longest(next) - longest(m)) / longest(m);
      drift = Math.max(drift, d);
      size = Math.max(size, s);
      minChange = Math.min(minChange, changed(cells[i], cells[(i + 1) % n]));
    });
    const seam = clip.loop && n > 1 ? Math.hypot(metrics[0].center.x - metrics[n - 1].center.x, metrics[0].center.y - metrics[n - 1].center.y) : NaN;
    if (state === "idle" || state === "move") {
      if (drift > DRIFT_ERROR) errors.push(`${id}/${state}: the pivot jumps ${drift.toFixed(3)} of the cell between frames`);
      else if (drift > DRIFT_WARN) warnings.push(`${id}/${state}: pivot drift up to ${drift.toFixed(3)} of the cell between frames`);
      if (size > SIZE_WARN) warnings.push(`${id}/${state}: visible size changes up to ${(size * 100).toFixed(0)} % between frames`);
      if (minChange < 0.001) warnings.push(`${id}/${state}: two neighbouring frames are identical`);
      // The resting body: union of the idle frames (move adds thrust), the reference for placement and size.
      if (state === "idle")
        for (const m of metrics) {
        if (m.coverage < 0.002) continue;
        const u = (union[id] ??= { x0: m.bounds.x0, y0: m.bounds.y0, x1: m.bounds.x1, y1: m.bounds.y1, size: clip.frameWidth });
        u.x0 = Math.min(u.x0, m.bounds.x0);
        u.y0 = Math.min(u.y0, m.bounds.y0);
        u.x1 = Math.max(u.x1, m.bounds.x1);
        u.y1 = Math.max(u.y1, m.bounds.y1);
      }
    }
    const avg = (f: (m: ArtMetrics) => number) => metrics.reduce((t, m) => t + f(m), 0) / Math.max(1, n);
    console.log(
      `${name}${String(n).padStart(4)}  ${clip.frameWidth}×${clip.frameHeight}  ${avg((m) => m.visibleWidth).toFixed(2)}×${avg((m) => m.visibleHeight).toFixed(2)} (avg)  ${f2(avg((m) => m.boundsCenter.x))}  ${f2(avg((m) => m.boundsCenter.y))}  ${avg((m) => m.coverage).toFixed(2)}   ${Math.max(...cells.map(visibleBorder)).toFixed(3)}   ${drift.toFixed(3)}      ${(size * 100).toFixed(0).padStart(3)} %    ${Number.isNaN(seam) ? "  -  " : seam.toFixed(3)}  ${(minChange * 100).toFixed(1)} %`,
    );
    if (args.includes("--frames"))
      metrics.forEach((m, i) => console.log(`    frame ${i + 1}: ${m.visibleWidth.toFixed(2)}×${m.visibleHeight.toFixed(2)} ctr ${f2(m.boundsCenter.x)} ${f2(m.boundsCenter.y)} cover ${m.coverage.toFixed(3)} edge ${visibleBorder(cells[i]).toFixed(3)}`));
  }
}
console.log(`\nSheets: ${(stored / 1e6).toFixed(1)} MB on disk, ${(decoded / 1e6).toFixed(1)} MB decoded RGBA (GPU textures, without mipmaps).`);

if (args.includes("--write")) {
  const lines = (Object.entries(union) as [EnemyId, NonNullable<(typeof union)[EnemyId]>][]).map(([id, u]) => {
    const r = (v: number) => Number(v.toFixed(4));
    return `  ${id}: { w: ${r((u.x1 - u.x0) / u.size)}, h: ${r((u.y1 - u.y0) / u.size)}, x: ${r((u.x0 + u.x1) / 2 / u.size - 0.5)}, y: ${r((u.y0 + u.y1) / 2 / u.size - 0.5)} },`;
  });
  writeFileSync(
    BOUNDS_FILE,
    `// Generated by scripts/audit-enemy-animations.ts -- --write. Do not edit by hand.\nimport type { EnemyId } from "../core/types";\nimport type { ArtBounds } from "./enemy-art";\n/** Visible bounds of the resting body (union of the idle frames) as a share of the animation cell. */\nexport const ANIMATION_BOUNDS: Readonly<Partial<Record<EnemyId, ArtBounds>>> = {\n${lines.join("\n")}\n};\n`,
  );
  console.log(`wrote ${BOUNDS_FILE.pathname}`);
}
for (const w of warnings) console.log(`WARN  ${w}`);
for (const e of errors) console.log(`ERROR ${e}`);
if (errors.length) process.exit(1);
